#include <iostream>
#include <thread>
#include <mutex>
#include <vector>
using namespace std;

class Counter {
    long value_ = 0;
public:
    // TODO: make add(long) and get() safe to call from several threads at once
    void add(long n) { value_ += n; }
    long get() const { return value_; }
};

int main() {
    Counter c;
    vector<thread> ts;
    for (int t = 0; t < 4; t++)
        ts.emplace_back([&c] { for (int i = 0; i < 25000; i++) c.add(1); });
    for (auto& t : ts) t.join();
    cout << c.get() << "\n";
}

challenges.solution:
#include <iostream>
#include <thread>
#include <mutex>
#include <vector>
using namespace std;

class Counter {
    mutable mutex m_;
    long value_ = 0;
public:
    void add(long n) {
        lock_guard<mutex> g(m_);
        value_ += n;
    }
    long get() const {
        lock_guard<mutex> g(m_);
        return value_;
    }
};

int main() {
    Counter c;
    vector<thread> ts;
    for (int t = 0; t < 4; t++)
        ts.emplace_back([&c] { for (int i = 0; i < 25000; i++) c.add(1); });
    for (auto& t : ts) t.join();
    cout << c.get() << "\n";
}
